import{bR as i,aL as a,v as s,H as e}from"./chunks/framework.DRjBupPc.js";const c=JSON.parse('{"title":"Skills","description":"为编码助手安装 TinyRobot Skill，获取组件使用建议和 Vue 示例指导。","frontmatter":{"title":"Skills","kind":"agent-doc","description":"为编码助手安装 TinyRobot Skill，获取组件使用建议和 Vue 示例指导。","status":"stable","keywords":["Agent Skills","TinyRobot Skill","Vue"]},"headers":[],"relativePath":"agents/skills.md","filePath":"agents/skills.md"}'),t={name:"agents/skills.md"};function o(n,l,k,d,p,r){return a(),s("div",null,[...l[0]||(l[0]=[e('<h1 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h1><blockquote><p>TinyRobot Skill 可以帮助编码助手更准确地理解 TinyRobot 项目，并在编写 Vue 代码时参考相应的组件用法和示例。</p></blockquote><h2 id="skill-可以帮你做什么" tabindex="-1">Skill 可以帮你做什么？ <a class="header-anchor" href="#skill-可以帮你做什么" aria-label="Permalink to &quot;Skill 可以帮你做什么？&quot;">​</a></h2><p>为编码助手安装 TinyRobot Skill 后，它可以在处理 TinyRobot 相关任务时：</p><ul><li>根据需求帮助选择合适的组件或功能；</li><li>结合组件文档和示例，说明如何配置和使用；</li><li>在编写 Vue 示例时补充必要的导入和使用前提；</li><li>对文档没有说明的 API 明确指出信息不足，而不是臆测不存在的属性或行为；</li><li>协助理解、编写和调整基于 TinyRobot 的聊天界面与交互代码。</li></ul><p>Skill 为编码助手提供 TinyRobot 相关的工作指引。组件的具体用法和示例仍以 TinyRobot 文档为准。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>请先确认你使用的编码助手支持以下安装方式。</p><h3 id="使用-skills-cli" tabindex="-1">使用 Skills CLI <a class="header-anchor" href="#使用-skills-cli" aria-label="Permalink to &quot;使用 Skills CLI&quot;">​</a></h3><p>Skills CLI 可用于将 TinyRobot Skill 安装到支持该格式的编码助手：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opentiny/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiny-robot-skill</span></span></code></pre></div><p>如果需要指定目标编码助手，可以根据 Skills CLI 的说明追加 <code>--agent</code> 参数。</p><h3 id="在-codex-中安装" tabindex="-1">在 Codex 中安装 <a class="header-anchor" href="#在-codex-中安装" aria-label="Permalink to &quot;在 Codex 中安装&quot;">​</a></h3><p>在 Codex 对话中调用内置的 <code>$skill-installer</code>，并提供 TinyRobot Skill 的仓库地址：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$skill-installer 请从 https://github.com/opentiny/agent-skills/tree/main/skills/tiny-robot-skill 安装 TinyRobot Skill。</span></span></code></pre></div><p>Codex 会从该仓库目录获取 Skill 并安装到本机。若安装后尚未出现在可用 Skill 中，可重新启动 Codex 再试。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p>安装完成后，直接描述你希望完成的 TinyRobot 任务即可。例如：</p><blockquote><p>请用 TinyRobot 的 Bubble 和 Sender 组件实现一个简单的聊天界面。先说明需要哪些组件，再给出包含导入语句的 Vue 示例。</p></blockquote><p>也可以让编码助手解释现有代码、调整组件配置，或根据文档示例补充交互。若它找不到对应 API 或示例，可以让它说明缺少的资料，再根据文档站中的组件说明继续确认。</p><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ul><li>尽可能说明你正在使用的组件、期望的交互和项目环境；</li><li>对涉及具体 API 的回答，要求编码助手给出对应的文档或示例依据；</li><li>生成代码后，仍应在自己的项目中检查导入路径、依赖和运行效果；</li><li>如果当前编码助手不支持 Skills 或对应安装方式，可直接查阅 TinyRobot 文档并把相关内容提供给它。</li></ul>',22)])])}const b=i(t,[["render",o]]);export{c as __pageData,b as default};
